@app.before_request
def require_login():
    allowed = ('login', 'serve_logo')
    if request.endpoint in allowed:
        return None
    if request.path.startswith('/logos/'):
        return None
    if request.path == '/login':
        return None
    if not session.get('logged_in'):
        if request.path.startswith('/api/'):
            return jsonify({"error": "غير مصرح"}), 401
        return redirect(url_for('login'))

app.config["MAX_CONTENT_LENGTH"] = 30 * 1024 * 1024

BASE_DIR = os.path.abspath(os.path.dirname(__file__))

# صورتا الغلاف والصفحة الختامية للتقرير الأسبوعي (من ملف العرض) - تُكتبان بجانب الملف عند التشغيل إن لم تكونا موجودتين
import base64
_WK_IMAGES = {
    'wk_cover.jpg': "",
    'wk_closing.jpg': "",
}
for _n, _b in _WK_IMAGES.items():
    _p = os.path.join(BASE_DIR, _n)
    if not os.path.exists(_p):
        try:
            with open(_p, 'wb') as _f:
                _f.write(base64.b64decode(_b))
        except OSError:
            pass


@app.route('/login', methods=['GET', 'POST'])
def login():
    error = None
    if request.method == 'POST':
        u = request.form.get('username','').strip()
        p = request.form.get('password','').strip()
        if u == APP_USERNAME and p == APP_PASSWORD:
            session['logged_in'] = True
            session['username'] = u
            return redirect(url_for('index'))
        else:
            error = 'اسم المستخدم أو كلمة المرور غلط'
    return render_template_string(LOGIN_HTML, error=error)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/logos/<filename>')
def serve_logo(filename):
    return send_from_directory(BASE_DIR, filename)

