@app.route('/api/archive/list')
def api_archive_list():
    days = []
    if os.path.isdir(ARCHIVE_DIR):
        for d in sorted(os.listdir(ARCHIVE_DIR), reverse=True):
            dp = os.path.join(ARCHIVE_DIR, d)
            if not (DATE_RE.match(d) and os.path.isdir(dp)):
                continue
            item = {'date': d, 'wos': [], 'works_pdf': '', 'daily_pdf': ''}
            if os.path.isfile(os.path.join(dp, 'تقرير_الأعمال_اليومية.pdf')):
                item['works_pdf'] = 'تقرير_الأعمال_اليومية.pdf'
