@app.route('/api/archive/next_sequence/<date>')
def api_archive_next_sequence(date):
    date = valid_date(date)
    if not os.path.isdir(ARCHIVE_DIR):
        return jsonify(start=316, max=315)
    max_seq = 315
    same_day = []
    seq_re = re.compile(r'-V-(\d+)$')
    for day_name in os.listdir(ARCHIVE_DIR):
        if not DATE_RE.match(day_name):
            continue
        day_dir = arch_path(day_name)
        if not os.path.isdir(day_dir):
            continue
        for folder in os.listdir(day_dir):
            wo_dir = os.path.join(day_dir, folder)
            if not os.path.isdir(wo_dir):
                continue
            info = read_json(os.path.join(wo_dir, 'wo.json'), {}) or {}
            report_name = str(info.get('reportName') or '')
            match = seq_re.search(report_name)
            if match:
                number = int(match.group(1))
                max_seq = max(max_seq, number)
                if day_name == date:
                    same_day.append(number)
    # إعادة حفظ نفس اليوم تحتفظ بأول رقم بدأ به هذا اليوم؛ اليوم الجديد يبدأ بعد أعلى رقم سابق.
    start = min(same_day) if same_day else max_seq + 1
    return jsonify(start=start, max=max_seq)


@app.route('/api/archive/collect_day', methods=['POST'])
def api_archive_collect_day():
    if request.remote_addr not in ('127.0.0.1', '::1'):
        abort(403)
    date = valid_date(request.form.get('date'))
    day_dir = arch_path(date)
    day = read_json(os.path.join(day_dir, 'day.json'), {}) or {}
    rows = day.get('rows') or []
    # مجلد واحد داخل أرشيف اليوم يحتوي نسخ ملفات PDF التسلسلية TBK فقط.
    target_root = arch_path(date, 'الملف التجميعي')
    os.makedirs(target_root, exist_ok=True)
    # احذف نسخ PDF السابقة حتى تعكس التجميعة آخر حالة محفوظة بالضبط.
    for old_name in os.listdir(target_root):
        old_path = os.path.join(target_root, old_name)
        if os.path.isfile(old_path) and old_name.lower().endswith('.pdf'):
            try: os.remove(old_path)
            except OSError: pass
    copied, missing = [], []
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            continue
        folder = clean_name(row.get('archFolder') or row.get('wo'), 'WO')
        wo_dir = arch_path(date, folder)
        info = read_json(os.path.join(wo_dir, 'wo.json'), {}) or {}
        report_name = clean_name(info.get('reportName') or row.get('reportName') or ('TBK-' + str(row.get('wo') or folder) + '-V-' + str(index + 1)), 'report')
        pdf_name = clean_name(info.get('pdf') or info.get('pdfName') or (report_name + '.pdf'), report_name + '.pdf')
        pdf_src = os.path.join(wo_dir, pdf_name)
        if not os.path.isfile(pdf_src):
            pdfs = sorted(n for n in os.listdir(wo_dir) if n.lower().endswith('.pdf')) if os.path.isdir(wo_dir) else []
            pdf_src = os.path.join(wo_dir, pdfs[0]) if pdfs else ''
        if pdf_src and os.path.isfile(pdf_src):
            out_name = report_name + '.pdf'
            shutil.copy2(pdf_src, os.path.join(target_root, out_name))
            copied.append(out_name)
        else:
            missing.append(str(row.get('wo') or folder))
    return jsonify(ok=True, path=target_root, copied=copied, missing=missing)


