@app.route('/api/archive/open', methods=['POST'])
def api_archive_open():
    date = valid_date(request.form.get('date'))
    folder = request.form.get('folder') or ''
    path = arch_path(date, clean_name(folder)) if folder else arch_path(date)
    if not os.path.isdir(path):
        abort(404)
    if sys.platform.startswith('win'):
        os.startfile(path)
    elif sys.platform == 'darwin':
        subprocess.Popen(['open', path])
    else:
        subprocess.Popen(['xdg-open', path])
    return jsonify(ok=True)


def _read_viols(day_dir):
    out = []
    for w in sorted(os.listdir(day_dir)):
        vd = os.path.join(day_dir, w, 'violations')
        if not os.path.isdir(vd):
            continue
        for n in sorted(os.listdir(vd)):
            info = read_json(os.path.join(vd, n, 'viol.json'))
            if isinstance(info, dict):
                info['folder'] = w
                info['vfolder'] = n
                out.append(info)
    return out


def _clear_files(folder):
    for fn in os.listdir(folder):
        p = os.path.join(folder, fn)
        if os.path.isfile(p):
            try:
                os.remove(p)
            except OSError:
                pass


