@app.route('/api/archive/range')
def api_archive_range():
    d1 = valid_date(request.args.get('from'))
    d2 = valid_date(request.args.get('to'))
    prior = set()
    days = []
    if os.path.isdir(ARCHIVE_DIR):
        for d in sorted(os.listdir(ARCHIVE_DIR)):
            dp = os.path.join(ARCHIVE_DIR, d)
            if not (DATE_RE.match(d) and os.path.isdir(dp)):
                continue
            day = read_json(os.path.join(dp, 'day.json'))
            if d < d1:
                if isinstance(day, dict):
                    for r in day.get('rows') or []:
                        w = str((r or {}).get('wo') or '').strip()
                        if w:
                            prior.add(w)
            elif d <= d2:
                days.append({'date': d, 'day': day if isinstance(day, dict) else None, 'viols': _read_viols(dp)})
    return jsonify(days=days, prior=sorted(prior))


